code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = all(grid[y][x] == color for y in range(r0, r1+1) for x in range(c0, c1+1)
                            if y in (r0, r1) or x in (c0, c1))
            if perimeter:
                frames.append((color, r0, r1, c0, c1, cells))
    patterned = []
    for frame in frames:
        color, r0, r1, c0, c1, _ = frame
        mask = [[grid[y][x] != 0 for x in range(c0+1, c1)] for y in range(r0+1, r1)]
        if any(any(row) for row in mask):
            patterned.append((frame, mask))
    if not patterned:
        return [row[:] for row in grid]
    source, mask = patterned[0]
    _, sr0, sr1, sc0, sc1, _ = source
    ih, iw = len(mask), len(mask[0])
    out = [row[:] for row in grid]
    for frame in frames:
        if frame is source:
            continue
        color, r0, r1, c0, c1, cells = frame
        for y, x in cells:
            out[y][x] = 0
        if r1-r0-1 == ih and c1-c0-1 == iw:
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if mask[y-r0-1][x-c0-1]:
                        out[y][x] = color
            # Restore the original complete frame border.
            for x in range(c0, c1+1):
                out[r0][x] = color; out[r1][x] = color
            for y in range(r0, r1+1):
                out[y][c0] = color; out[y][c1] = color
    return out
'''
